12	struct TritonKernelSpec {
13	    artifact_dir: &'static str,
14	    kernel_path: &'static str,
15	    kernel_name: &'static str,
16	    signature: &'static str,
17	    grid: &'static str,
18	    out_name: &'static str,
19	    num_warps: u32,
20	    num_stages: u32,
21	}
22	
23	struct NvccTask {
24	    cu_file: PathBuf,
25	    obj_file: PathBuf,
26	    args: Vec<String>,
27	}
28	
29	struct FlashInferIncludes {
30	    include: PathBuf,
31	    csrc: PathBuf,
32	    cutlass: PathBuf,
33	    cutlass_util: PathBuf,
34	    spdlog: PathBuf,
35	    /// Vendored CCCL (cub, libcudacxx, thrust). Must be passed as `-I` while the
36	    /// CTK include dir is `-isystem`, so these override the toolkit's older CCCL
37	    /// copy — FlashInfer v0.6+ uses APIs (e.g. `cuda::fast_mod_div`) that older
38	    /// CTK CCCL lacks. Mirrors upstream flashinfer/jit/cpp_ext.py ordering.
39	    cccl: Vec<PathBuf>,
40	}
41	
42	const GLM52_TRTLLM_FMHA_CUBINS: &[(&str, &str)] = &[
43	    (
44	        "kGlm52FmhaSparseSeedQ8",
45	        "fmhaSm100fKernel_QkvE4m3OBfloat16HQk576HV512PagedKvDenseStaticTokenSparseP1MultiCtasKvVarSeqQ8Kv128StaticSwapsAbForGen.cubin",
46	    ),
47	    (
48	        "kGlm52FmhaSparsePersistentSeedQ8",
49	        "fmhaSm100fKernel_QkvE4m3OBfloat16HQk576HV512PagedKvDenseStaticTokenSparseP1VarSeqQ8Kv128PersistentSwapsAbForGen.cubin",
50	    ),
51	    (
52	        "kGlm52FmhaSparseShortQ8",
53	        "fmhaSm100fKernel_QkvE4m3OBfloat16HQk576HV512HVPerCta128PagedKvDenseStaticTokenSparseP1VarSeqQ8Kv128PersistentSwapsAbForGen.cubin",
54	    ),
55	    (
56	        "kGlm52FmhaSparseLongQ8",
57	        "fmhaSm100fKernel_QkvE4m3OBfloat16HQk576HV512HVPerCta128PagedKvDenseStaticTokenSparseP1MultiCtasKvVarSeqQ8Kv128StaticSwapsAbForGen.cubin",
58	    ),
59	    (
60	        "kGlm52FmhaSparseLongQ16",
61	        "fmhaSm100fKernel_QkvE4m3OBfloat16HQk576HV512HVPerCta128PagedKvDenseStaticTokenSparseP1MultiCtasKvVarSeqQ16Kv128StaticSwapsAbForGen.cubin",
62	    ),
63	    (
64	        "kGlm52FmhaSparseLongQ16V256",
65	        "fmhaSm100fKernel_QkvE4m3OBfloat16HQk576HV512HVPerCta256PagedKvDenseStaticTokenSparseP1MultiCtasKvVarSeqQ16Kv128StaticSwapsAbForGen.cubin",
66	    ),
67	    (
68	        "kGlm52FmhaSparseLongQ16V512",
69	        "fmhaSm100fKernel_QkvE4m3OBfloat16HQk576HV512PagedKvDenseStaticTokenSparseP1MultiCtasKvVarSeqQ16Kv128StaticSwapsAbForGen.cubin",
70	    ),
71	];
72	
73	fn generate_glm52_trtllm_fmha_cubins(root: &Path, out_dir: &Path) {
74	    let cubin_dir = root.join("cubin/glm52");
75	    let mut generated = String::from(
76	        "// Generated by pegainfer-kernels/build.rs from the checked-in FlashInfer cubins.\n\
77	         #pragma once\n\n",
78	    );
79	    for &(symbol, file_name) in GLM52_TRTLLM_FMHA_CUBINS {
80	        let path = cubin_dir.join(file_name);
81	        println!("cargo:rerun-if-changed={}", path.display());
82	        let bytes = fs::read(&path).unwrap_or_else(|err| {
83	            panic!(
84	                "failed to read GLM5.2 TRTLLM FMHA cubin {}: {err}",
85	                path.display()
86	            )
87	        });
88	        writeln!(&mut generated, "static const unsigned char {symbol}[] = {{")
89	            .expect("write cubin array declaration");
90	        for chunk in bytes.chunks(16) {
91	            generated.push_str("  ");
92	            for byte in chunk {
93	                write!(&mut generated, "0x{byte:02x}, ").expect("write cubin byte");
94	            }
95	            generated.push('\n');
96	        }
97	        generated.push_str("};\n");
98	        writeln!(
99	            &mut generated,
100	            "static constexpr unsigned int {symbol}Size = sizeof({symbol});\n"
101	        )
102	        .expect("write cubin array size");
103	    }
104	    let output = out_dir.join("glm52_trtllm_fmha_cubins.inc");
105	    fs::write(&output, generated).unwrap_or_else(|err| {
106	        panic!(
107	            "failed to write generated GLM5.2 TRTLLM FMHA cubin header {}: {err}",
108	            output.display()
109	        )
110	    });
111	}
112	
113	fn workspace_root() -> PathBuf {
114	    crate_root().join("..")
115	}
116	
117	/// AOT-export the CuTe DSL tcgen05 fp8 GEMMs and compile the dispatch shim
118	/// around them (csrc/glm52/glm52_fp8_dsl_gemm.c). Opt-in via
119	/// `PEGAINFER_CUTEDSL_PYTHON` (a Python with torch + nvidia-cutlass-dsl on a
120	/// CUDA box); without it the shim compiles as an empty-table stub and the
121	/// runtime stays on the CUTLASS route. The exported objects resolve their
122	/// `_cuda*` wrapper symbols from the DSL wheel's libcute_dsl_runtime.so —
123	/// linked here, needed on LD_LIBRARY_PATH at run time.
124	fn build_glm52_cutedsl_fp8_dsl(root: &Path, out_dir: &Path, cuda_include: &Path) {
125	    println!("cargo:rerun-if-env-changed=PEGAINFER_CUTEDSL_PYTHON");
126	    let shim_c = root.join("csrc/glm52/glm52_fp8_dsl_gemm.c");
127	    println!("cargo:rerun-if-changed={}", shim_c.display());
128	    let mut shim = cc::Build::new();
129	    shim.include(cuda_include)
130	        .flag("-std=c11")
131	        .warnings(false)
132	        .file(&shim_c);
133	    if let Ok(python) = std::env::var("PEGAINFER_CUTEDSL_PYTHON") {
134	        let script = root.join("tools/cutedsl/export_glm52_fp8_dsl.py");
135	        let benches = workspace_root().join("pegainfer-glm52/benches");
136	        let gen_dir = out_dir.join("cutedsl_fp8_dsl");
137	        fs::create_dir_all(&gen_dir).expect("create the cutedsl gen dir");
138	        println!("cargo:rerun-if-changed={}", script.display());
139	        for source in [
140	            "kernel_lab/units/fp8_gemm_dsl_tc_kernel.py",
141	            "kernel_lab/units/fp8_gemm_dsl_tc.py",
142	        ] {
143	            println!("cargo:rerun-if-changed={}", benches.join(source).display());
144	        }
145	        let status = time_phase("cutedsl fp8 GEMM export", || {
146	            Command::new(&python)
147	                .arg(&script)
148	                .arg("--benches-dir")
149	                .arg(&benches)
150	                .arg("--out-dir")
151	                .arg(&gen_dir)
152	                .status()
153	        })
154	        .unwrap_or_else(|err| panic!("failed to run {python}: {err}"));
155	        assert!(
156	            status.success(),
157	            "CuTe DSL fp8 GEMM export failed (PEGAINFER_CUTEDSL_PYTHON={python})"
158	        );
159	        let mut objects: Vec<PathBuf> = fs::read_dir(&gen_dir)
160	            .expect("read the cutedsl gen dir")
161	            .filter_map(|entry| {
162	                let path = entry.ok()?.path();
163	                (path.extension().and_then(|e| e.to_str()) == Some("o")).then_some(path)
164	            })
165	            .collect();
166	        objects.sort();
167	        assert!(!objects.is_empty(), "cutedsl export produced no objects");
168	        let object_count = objects.len();
169	        for object in objects {
170	            shim.object(object);
171	        }
172	        shim.define("GLM52_CUTEDSL_AOT", None).include(&gen_dir);
173	        let lib_dir_probe = Command::new(&python)
174	            .args([
175	                "-c",
176	                "import cutlass, os; print(os.path.abspath(os.path.join(os.path.dirname(cutlass.__file__), '..', '..', 'lib')))",
177	            ])
178	            .output()
179	            .expect("probe the nvidia-cutlass-dsl lib dir");
180	        let lib_dir = String::from_utf8_lossy(&lib_dir_probe.stdout)
181	            .trim()
182	            .to_string();
183	        assert!(
184	            Path::new(&lib_dir).join("libcute_dsl_runtime.so").exists(),
185	            "libcute_dsl_runtime.so not found under {lib_dir}"
186	        );
187	        println!("cargo:rustc-link-search=native={lib_dir}");
188	        println!("cargo:rustc-link-lib=dylib=cute_dsl_runtime");
189	        println!(
190	            "cargo:warning=GLM5.2 CuTe DSL fp8 GEMM AOT enabled: {object_count} objects; \
191	             libcute_dsl_runtime.so ({lib_dir}) must be on LD_LIBRARY_PATH at run time"
192	        );
193	    }
194	    time_phase("cc glm52_fp8_dsl_gemm", || {
195	        shim.compile("glm52_fp8_dsl_gemm");
196	    });
197	}
198	
199	fn crate_root() -> PathBuf {
200	    PathBuf::from(std::env::var("CARGO_MANIFEST_DIR").expect("CARGO_MANIFEST_DIR not set"))
201	}
202	
203	fn ensure_git_submodules_initialized(repo_root: &Path) {
204	    if !repo_root.join(".git").exists() || !repo_root.join(".gitmodules").is_file() {
205	        return;
206	    }
207	
208	    println!(
209	        "cargo:rerun-if-changed={}",
210	        repo_root.join(".gitmodules").display()
211	    );
212	
213	    let output = Command::new("git")
214	        .args(["submodule", "status", "--recursive"])
215	        .current_dir(repo_root)
216	        .output()
217	        .unwrap_or_else(|err| {
218	            panic!(
219	                "Failed to inspect git submodules from {}: {err}. \
220	                 Install git or run `git submodule update --init --recursive` manually.",
221	                repo_root.display()
222	            )
223	        });
224	    assert!(
225	        output.status.success(),
226	        "Failed to inspect git submodules from {}. stdout: {} stderr: {}",
227	        repo_root.display(),
228	        String::from_utf8_lossy(&output.stdout).trim(),
229	        String::from_utf8_lossy(&output.stderr).trim()
230	    );
231	
232	    if !String::from_utf8_lossy(&output.stdout)
233	        .lines()
234	        .any(|line| line.starts_with('-'))
235	    {
236	        return;
237	    }
238	
239	    println!("cargo:warning=Initializing missing git submodules for first build");
240	    let output = Command::new("git")
241	        .args(["submodule", "update", "--init", "--recursive"])
242	        .current_dir(repo_root)
243	        .output()
244	        .unwrap_or_else(|err| {
245	            panic!(
246	                "Failed to initialize git submodules from {}: {err}. \
247	                 Run `git submodule update --init --recursive` manually.",
248	                repo_root.display()
249	            )
250	        });
251	    assert!(
252	        output.status.success(),
253	        "Failed to initialize git submodules from {}. stdout: {} stderr: {}",
254	        repo_root.display(),
255	        String::from_utf8_lossy(&output.stdout).trim(),
256	        String::from_utf8_lossy(&output.stderr).trim()
257	    );
258	}
259	
260	fn build_timing_enabled() -> bool {
261	    std::env::var("PEGAINFER_BUILD_TIMING").is_ok_and(|value| {
262	        let value = value.trim().to_ascii_lowercase();
263	        !(value.is_empty() || value == "0" || value == "false" || value == "off")
