547	fn glm52_flashmla_sparse_arch_args(normalized_sms: &[String], nvcc: &str) -> Vec<String> {
548	    let sm90a_supported = normalized_sms.iter().any(|sm| sm == "90" || sm == "90a")
549	        && nvcc_accepts_gencode(nvcc, "90a", "90a");
550	    let sm100f_supported = normalized_sms
551	        .iter()
552	        .any(|sm| sm_numeric_prefix(sm).is_some_and(|n| (100..120).contains(&n)))
553	        && nvcc_accepts_gencode(nvcc, "100f", "100f");
554	
555	    let mut targets = Vec::new();
556	    for sm in normalized_sms {
557	        let target = match sm_numeric_prefix(sm) {
558	            Some(90) => {
559	                if sm90a_supported {
560	                    Some(("90a", "90a", "sm_90a"))
561	                } else {
562	                    println!(
563	                        "cargo:warning=nvcc cannot compile compute_90a/sm_90a; GLM5.2 FlashMLA sparse decode will use sm_{sm}"
564	                    );
565	                    Some((sm.as_str(), sm.as_str(), "native"))
566	                }
567	            }
568	            Some(100..=119) => {
569	                if sm100f_supported {
570	                    Some(("100f", "100f", "sm_100f"))
571	                } else {
572	                    println!(
573	                        "cargo:warning=nvcc cannot compile compute_100f/sm_100f; GLM5.2 FlashMLA sparse decode will use sm_{sm}"
574	                    );
575	                    Some((sm.as_str(), sm.as_str(), "native"))
576	                }
577	            }
578	            _ => Some((sm.as_str(), sm.as_str(), "native")),
579	        };
580	        if let Some(target) = target {
581	            if !targets.iter().any(|existing| existing == &target) {
582	                targets.push(target);
583	            }
584	        }
585	    }
586	
587	    let labels = targets
588	        .iter()
589	        .map(|(_, sm, label)| {
590	            if *label == "native" {
591	                format!("sm_{sm}")
592	            } else {
593	                label.to_string()
594	            }
595	        })
596	        .collect::<Vec<_>>();
597	    if labels
598	        != normalized_sms
599	            .iter()
600	            .map(|sm| format!("sm_{sm}"))
601	            .collect::<Vec<_>>()
602	    {
603	        println!(
604	            "cargo:warning=Compiling GLM5.2 FlashMLA sparse decode for nvcc targets: {}",
605	            labels.join(",")
606	        );
607	    }
608	
609	    let mut args = Vec::new();
610	    for (compute, sm, _) in targets {
611	        args.push("-gencode".to_string());
612	        args.push(format!("arch=compute_{compute},code=sm_{sm}"));
613	    }
614	    args
615	}
