689	fn collect_files_recursively(dir: &Path, out: &mut Vec<PathBuf>) {
690	    let mut entries: Vec<_> = std::fs::read_dir(dir)
691	        .unwrap_or_else(|err| panic!("Failed to read {}: {err}", dir.display()))
692	        .map(|entry| {
693	            entry.unwrap_or_else(|err| panic!("Failed to read entry in {}: {err}", dir.display()))
694	        })
695	        .collect();
696	    entries.sort_by_key(std::fs::DirEntry::path);
697	
698	    for entry in entries {
699	        let path = entry.path();
700	        if path.is_dir() {
701	            collect_files_recursively(&path, out);
702	        } else {
703	            out.push(path);
704	        }
705	    }
706	}
