853	/// NCCL >= 2.30.4 root (include/nccl.h + lib/libnccl.so.2) for the DeepEP
854	/// shim's device API (ncclDevComm / windows / GIN). cudarc dlopens whatever
855	/// libnccl.so.2 it finds at runtime, so build and runtime must point at the
856	/// same install: set PEGAINFER_NCCL_ROOT and put `$PEGAINFER_NCCL_ROOT/lib`
857	/// on LD_LIBRARY_PATH. The nvidia-nccl-cu13 wheel layout works directly:
858	///   pip download 'nvidia-nccl-cu13>=2.30.4' --no-deps -d /tmp/nccl \
859	///     && unzip /tmp/nccl/*.whl 'nvidia/nccl/*' -d /tmp/nccl \
860	///     && export PEGAINFER_NCCL_ROOT=/tmp/nccl/nvidia/nccl
861	fn deepep_nccl_root() -> PathBuf {
862	    let Ok(root) = std::env::var("PEGAINFER_NCCL_ROOT").map(PathBuf::from) else {
863	        panic!(
864	            "The moe feature builds the DeepEP shim, which needs NCCL >= 2.30.4. \
865	             Set PEGAINFER_NCCL_ROOT to an install with include/nccl.h and lib/libnccl.so.2 \
866	             (e.g. the unpacked nvidia-nccl-cu13 wheel)."
867	        )
868	    };
869	
870	    let header = root.join("include/nccl.h");
871	    let contents = fs::read_to_string(&header).unwrap_or_else(|err| {
872	        panic!(
873	            "PEGAINFER_NCCL_ROOT: cannot read {}: {err}",
874	            header.display()
875	        )
876	    });
877	    let version_component = |name: &str| -> u32 {
878	        contents
879	            .lines()
880	            .find_map(|line| line.strip_prefix(&format!("#define {name} ")))
881	            .and_then(|value| value.trim().parse().ok())
882	            .unwrap_or_else(|| panic!("{} does not define {name}", header.display()))
883	    };
884	    let version = version_component("NCCL_MAJOR") * 10000
885	        + version_component("NCCL_MINOR") * 100
886	        + version_component("NCCL_PATCH");
887	    assert!(
888	        version >= 23004,
889	        "PEGAINFER_NCCL_ROOT points at NCCL {version} (< 2.30.4); the DeepEP shim needs the \
890	         NCCL device API"
891	    );
892	
893	    let lib = root.join("lib/libnccl.so.2");
894	    assert!(
895	        lib.is_file(),
896	        "PEGAINFER_NCCL_ROOT: {} not found",
897	        lib.display()
898	    );
899	    root
900	}
