902	/// The wheel ships only libnccl.so.2; give the linker the unversioned name it
903	/// wants via a symlink in OUT_DIR (already on the link search path). The
904	/// resulting DT_NEEDED is the soname (libnccl.so.2), resolved at runtime from
905	/// LD_LIBRARY_PATH.
906	fn link_deepep_nccl(nccl_root: &Path, out_dir: &Path) {
907	    let link_name = out_dir.join("libnccl.so");
908	    let target = nccl_root.join("lib/libnccl.so.2");
909	    match fs::read_link(&link_name) {
910	        Ok(existing) if existing == target => {}
911	        _ => {
912	            let _ = fs::remove_file(&link_name);
913	            std::os::unix::fs::symlink(&target, &link_name)
914	                .unwrap_or_else(|err| panic!("Failed to symlink {}: {err}", link_name.display()));
915	        }
916	    }
917	    println!("cargo:rustc-link-lib=dylib=nccl");
918	}
