920	/// Link the freshly compiled CUDA objects into `libglm52_kernel_lab.so` for
921	/// the kernel-lab Python harness (`PEGAINFER_KERNEL_LAB=1` only). The objects
922	/// are already PIC (every nvcc task adds `--compiler-options -fPIC`), so the
923	/// same .o files that feed `libkernels_cuda.a` link into a shared object
924	/// without a second compile pass. DeepEP shim objects reference NCCL symbols
925	/// that stay unresolved in the .so — the harness dlopens with `RTLD_LAZY` and
926	/// never calls into DeepEP for these units.
927	fn link_kernel_lab_shared(
928	    nvcc: &str,
929	    toolkit: &pegainfer_build::CudaToolkit,
930	    out_dir: &Path,
931	    obj_files: &[PathBuf],
932	) {
933	    let so_path = out_dir.join("libglm52_kernel_lab.so");
934	    let _ = fs::remove_file(&so_path);
935	    let mut args = vec!["-shared".to_string()];
936	    args.extend(
937	        obj_files
938	            .iter()
939	            .map(|path| path.to_string_lossy().to_string()),
940	    );
941	    args.extend([
942	        "-o".to_string(),
943	        so_path.to_string_lossy().to_string(),
944	        format!("-L{}", toolkit.root.join("lib64").display()),
945	        "-lcudart".to_string(),
946	        "-lcublas".to_string(),
947	        "-lcublasLt".to_string(),
948	        "-lnvrtc".to_string(),
949	        "-lcuda".to_string(),
950	        "-lstdc++".to_string(),
951	    ]);
952	    let status = time_phase("nvcc -shared libglm52_kernel_lab.so", || {
953	        nvcc_command(nvcc)
954	            .args(&args)
955	            .status()
956	            .expect("Failed to run nvcc for libglm52_kernel_lab.so")
957	    });
958	    assert!(status.success(), "kernel-lab shared link failed");
959	
960	    // Stable discovery path: OUT_DIR is target/<profile>/build/<pkg>-<hash>/out,
961	    // so three parents up is target/<profile>.
962	    if let Some(profile_dir) = out_dir
963	        .parent()
964	        .and_then(Path::parent)
965	        .and_then(Path::parent)
966	    {
967	        let stable = profile_dir.join("libglm52_kernel_lab.so");
968	        fs::copy(&so_path, &stable).unwrap_or_else(|err| {
969	            panic!(
970	                "Failed to copy kernel-lab .so to {}: {err}",
971	                stable.display()
972	            )
973	        });
974	        println!("cargo:warning=kernel_lab .so: {}", stable.display());
975	    } else {
976	        println!(
977	            "cargo:warning=kernel_lab .so: {} (no stable target/<profile> copy)",
978	            so_path.display()
979	        );
980	    }
981	}
