983	fn cuda_object_name(csrc_dir: &Path, cu_file: &Path) -> String {
984	    let Some(relative) = cu_file.strip_prefix(csrc_dir).ok() else {
985	        return format!("{}_cuda.o", cu_file.file_stem().unwrap().to_string_lossy());
986	    };
987	
988	    let mut parts: Vec<String> = relative
989	        .components()
990	        .filter_map(|component| component.as_os_str().to_str().map(ToOwned::to_owned))
991	        .collect();
992	    if let Some(last) = parts.last_mut() {
993	        if let Some(stem) = Path::new(last).file_stem().and_then(|stem| stem.to_str()) {
994	            *last = stem.to_string();
995	        }
996	    }
997	
998	    format!("{}_cuda.o", parts.join("_"))
999	}
