1017	fn find_triton_python() -> Result<String, String> {
1018	    if let Ok(candidate) = std::env::var("PEGAINFER_TRITON_PYTHON") {
1019	        let candidate = candidate.trim();
1020	        if candidate.is_empty() {
1021	            return Err(
1022	                "PEGAINFER_TRITON_PYTHON is set but empty. See pegainfer-kernels/tools/triton/README.md.".to_string(),
1023	            );
1024	        }
1025	        return probe_triton_python(candidate).map_err(|message| {
1026	            format!(
1027	                "PEGAINFER_TRITON_PYTHON=`{candidate}` could not import Triton. {message}. See pegainfer-kernels/tools/triton/README.md."
1028	            )
1029	        });
1030	    }
1031	
1032	    let local_venv = workspace_root().join(".venv/bin/python");
1033	    let mut diagnostics = Vec::new();
1034	    let mut candidates = Vec::new();
1035	    if local_venv.exists() {
1036	        candidates.push(local_venv.to_string_lossy().to_string());
1037	    }
1038	    candidates.extend(["python3".to_string(), "python".to_string()]);
1039	
1040	    for candidate in candidates {
1041	        match probe_triton_python(&candidate) {
1042	            Ok(path) => return Ok(path),
1043	            Err(message) => diagnostics.push(message),
1044	        }
1045	    }
1046	
1047	    Err(format!(
1048	        "Could not find a Python interpreter with Triton installed. Set PEGAINFER_TRITON_PYTHON, bootstrap .venv, or ensure `python3 -c 'import triton'` works. Probe results: {}.",
1049	        diagnostics.join(" | ")
1050	    ))
1051	}
