1242	fn patch_triton_aot_per_device_handles(c_path: &Path) {
1243	    let src = fs::read_to_string(c_path).expect("failed to read generated Triton C source");
1244	    let module_name = src
1245	        .lines()
1246	        .find_map(|line| line.strip_prefix("CUmodule "))
1247	        .and_then(|rest| rest.strip_suffix(" = NULL;"))
1248	        .map(str::to_string)
1249	        .expect("generated Triton C source should declare one CUmodule");
1250	    let function_name = src
1251	        .lines()
1252	        .find_map(|line| line.strip_prefix("CUfunction "))
1253	        .and_then(|rest| rest.strip_suffix(" = NULL;"))
1254	        .map(str::to_string)
1255	        .expect("generated Triton C source should declare one CUfunction");
1256	
1257	    let device_table_define = "#define PEGAINFER_TRITON_DEVICE_TABLE_SIZE 16\n\n";
1258	    let device_helper = "\n\nstatic CUresult pegainfer_triton_current_device(CUdevice *dev) {\n  CUresult err = cuCtxGetDevice(dev);\n  if (err != CUDA_SUCCESS) {\n    return err;\n  }\n  if (*dev < 0 || *dev >= PEGAINFER_TRITON_DEVICE_TABLE_SIZE) {\n    return CUDA_ERROR_INVALID_DEVICE;\n  }\n  return CUDA_SUCCESS;\n}";
1259	
1260	    let patched = src
1261	        .replace(
1262	            &format!("CUmodule {module_name} = NULL;"),
1263	            &format!(
1264	                "{device_table_define}CUmodule {module_name}[PEGAINFER_TRITON_DEVICE_TABLE_SIZE] = {{0}};"
1265	            ),
1266	        )
1267	        .replace(
1268	            &format!("CUfunction {function_name} = NULL;"),
1269	            &format!(
1270	                "CUfunction {function_name}[PEGAINFER_TRITON_DEVICE_TABLE_SIZE] = {{0}};{device_helper}"
1271	            ),
1272	        )
1273	        .replace(
1274	            &format!("CUDA_CHECK(cuModuleUnload({module_name}));"),
1275	            &format!(
1276	                "CUdevice dev = 0;\n    CUDA_CHECK(pegainfer_triton_current_device(&dev));\n    if ({module_name}[dev] != NULL) {{\n      CUDA_CHECK(cuModuleUnload({module_name}[dev]));\n      {module_name}[dev] = NULL;\n      {function_name}[dev] = NULL;\n    }}"
1277	            ),
1278	        );
1279	    let patched = patched
1280	        .replace(
1281	            &format!("cuModuleLoadData(&{module_name}, bin)"),
1282	            &format!("cuModuleLoadData(&{module_name}[dev], bin)"),
1283	        )
1284	        .replace(
1285	            &format!("cuModuleGetFunction(&{function_name}, {module_name}, "),
1286	            &format!("cuModuleGetFunction(&{function_name}[dev], {module_name}[dev], "),
1287	        )
1288	        .replace(
1289	            &format!("cuFuncSetCacheConfig({function_name}, "),
1290	            &format!("cuFuncSetCacheConfig({function_name}[dev], "),
1291	        )
1292	        .replace(
1293	            &format!("cuFuncSetAttribute({function_name}, "),
1294	            &format!("cuFuncSetAttribute({function_name}[dev], "),
1295	        )
1296	        .replace(
1297	            &format!("if ({function_name} == NULL)\n       load_"),
1298	            &format!("CUdevice dev = 0;\n    CUDA_CHECK(pegainfer_triton_current_device(&dev));\n    if ({function_name}[dev] == NULL)\n       load_"),
1299	        )
1300	        .replace(
1301	            &format!("return cuLaunchKernel({function_name}, "),
1302	            &format!("return cuLaunchKernel({function_name}[dev], "),
1303	        )
1304	        .replace(
1305	            "int dev = 0;\n    void *bin =",
1306	            "CUdevice dev = 0;\n    CUDA_CHECK(pegainfer_triton_current_device(&dev));\n    void *bin =",
1307	        );
1308	
1309	    fs::write(c_path, patched).expect("failed to patch generated Triton C source");
1310	}
