1532	// ===========================================================================
1533	// tilelang: BEGIN — TileLang AOT kernel families.
1534	//
1535	// Self-contained section: everything a model line needs to turn its
1536	// `generate.py` into objects lives between these two markers plus one
1537	// `cfg!(feature = ...)` block per family inside `main`. A family is a row in
1538	// the table below; the tiers, the arch handling and the nvcc flags are shared.
1539	//
1540	// Three tiers, first one that works wins:
1541	//   1. generate — run the generator with a build-host Python that has the
1542	//      pinned TileLang. Preferred; this is what a dev box and the GPU CI
1543	//      builders take.
1544	//   2. pre-generated — `PEGAINFER_<label>_TILELANG_PREGEN=<dir>` points at a
1545	//      directory produced earlier by `generate.py --vendor-includes`, for
1546	//      hosts that cannot install TileLang. The directory carries its own
1547	//      `manifest.txt` with the CUDA files and header include paths.
1548	//   3. stub — no Python, no pre-generated dir: compile launchers that return
1549	//      `cudaErrorNotSupported`, so a featureless/CI build stays green and a
1550	//      call fails loudly instead of silently computing garbage.
1551	// ===========================================================================
1552	
1553	struct TileLangArtifacts {
1554	    cu_files: Vec<PathBuf>,
1555	    template_include: PathBuf,
1556	    cutlass_include: PathBuf,
1557	    /// nvcc flags the generator states its bodies were compiled with; leaving
1558	    /// one out is a silent numerical difference from the gated kernel.
1559	    nvcc_flags: Vec<String>,
1560	    /// Entry points the generator says it emitted, as `(name, parameters)`.
1561	    /// C has no mangling, so a stub whose parameters drifted from the real
1562	    /// launcher would link and then be called wrongly; these are checked
1563	    /// against the family's own list instead.
1564	    launchers: Vec<(String, String)>,
1565	    /// Arch the bodies were lowered for, e.g. `sm_103a`.
1566	    arch: Option<String>,
1567	    /// The attention geometry the bodies were compiled for. Re-exported, so
1568	    /// a caller refuses another checkpoint before it loads weights.
1569	    geometry: Option<String>,
1570	    /// Dynamic shared memory one block opts into. A device whose per-block
1571	    /// limit is under it cannot run the bodies at all.
1572	    smem: Option<String>,
1573	}
1574	
1575	/// One model line's TileLang kernels. `label` names the family in warnings,
1576	/// in its `PEGAINFER_<label>_TILELANG_*` variables and, lowercased, in its
1577	/// artifact directory and stub file, so a family is this row and nothing else.
1578	struct TileLangFamily {
1579	    label: &'static str,
1580	    /// Generator, relative to the workspace root.
1581	    generator: &'static str,
1582	    /// Further inputs the generator reads, for rerun tracking.
1583	    sources: &'static [&'static str],
1584	    /// `extern "C"` entry points the generator emits; the stub tier has to
1585	    /// match this list exactly or the feature fails to link.
1586	    launchers: &'static [(&'static str, &'static str)],
1587	    /// Lowest SM the lowering supports; below it the build takes the stub.
1588	    min_sm: u32,
1589	    /// Manifest keys the crate re-exports for a run-time refusal. A directory
1590	    /// that predates one of them would leave that refusal fail-open, so it is
1591	    /// rejected here rather than skipped.
1592	    required_manifest: &'static [&'static str],
1593	}
1594	
1595	impl TileLangFamily {
1596	    /// The `cfg` a caller reads to know real bodies were built, not stubs.
1597	    fn cfg(&self) -> String {
1598	        format!("{}_tilelang", self.label.to_lowercase())
1599	    }
1600	}
