1826	/// Parse the `KEY=VALUE` contract the generator prints on stdout and mirrors
1827	/// into `manifest.txt` (a generator that cannot lower for this build prints
1828	/// one `UNAVAILABLE=<reason>` line instead, and the family takes the stub
1829	/// tier): one `CU_PATH` per emitted translation unit, the two
1830	/// header roots the generated CUDA includes, and the arch the bodies were
1831	/// lowered for. Paths resolve against `base`, the directory the manifest
1832	/// describes, so a vendored directory answers for its own files wherever it
1833	/// was copied; an absolute entry passes through unchanged.
1834	fn parse_tilelang_manifest(text: &str, origin: &str, base: &Path) -> TileLangArtifacts {
1835	    let mut cu_files = Vec::new();
1836	    let mut template_include = None;
1837	    let mut cutlass_include = None;
1838	    let mut arch = None;
1839	    let mut geometry = None;
1840	    let mut smem = None;
1841	    let mut nvcc_flags = Vec::new();
1842	    let mut launchers = Vec::new();
1843	    for line in text.lines() {
1844	        if let Some(value) = line.strip_prefix("CU_PATH=") {
1845	            cu_files.push(base.join(value.trim()));
1846	        } else if let Some(value) = line.strip_prefix("TILELANG_TEMPLATE_PATH=") {
1847	            template_include = Some(base.join(value.trim()));
1848	        } else if let Some(value) = line.strip_prefix("CUTLASS_INCLUDE_DIR=") {
1849	            cutlass_include = Some(base.join(value.trim()));
1850	        } else if let Some(value) = line.strip_prefix("ARCH=") {
1851	            arch = Some(value.trim().to_string());
1852	        } else if let Some(value) = line.strip_prefix("GEOMETRY=") {
1853	            geometry = Some(value.trim().to_string());
1854	        } else if let Some(value) = line.strip_prefix("SMEM=") {
1855	            smem = Some(value.trim().to_string());
1856	        } else if let Some(value) = line.strip_prefix("NVCC_FLAG=") {
1857	            nvcc_flags.push(value.trim().to_string());
1858	        } else if let Some(value) = line.strip_prefix("LAUNCHER=") {
1859	            let (name, params) = value
1860	                .trim()
1861	                .split_once('|')
1862	                .unwrap_or_else(|| panic!("{origin} has a LAUNCHER without parameters: {value}"));
1863	            launchers.push((name.to_string(), params.to_string()));
1864	        }
1865	    }
1866	
1867	    assert!(!cu_files.is_empty(), "{origin} listed no CU_PATH");
1868	    let template_include =
1869	        template_include.unwrap_or_else(|| panic!("{origin} listed no TILELANG_TEMPLATE_PATH"));
1870	    let cutlass_include =
1871	        cutlass_include.unwrap_or_else(|| panic!("{origin} listed no CUTLASS_INCLUDE_DIR"));
1872	    for cu_file in &cu_files {
1873	        assert!(
1874	            cu_file.exists(),
1875	            "{origin} lists a missing CUDA file: {}",
1876	            cu_file.display()
1877	        );
1878	    }
1879	
1880	    TileLangArtifacts {
1881	        cu_files,
1882	        template_include,
1883	        cutlass_include,
1884	        nvcc_flags,
1885	        launchers,
1886	        arch,
1887	        geometry,
1888	        smem,
1889	    }
1890	}
