1893	fn same_parameters(left: &str, right: &str) -> bool {
1894	    let normalize = |text: &str| {
1895	        text.split(',')
1896	            .map(|part| part.split_whitespace().collect::<Vec<_>>().join(" "))
1897	            .collect::<Vec<_>>()
1898	    };
1899	    normalize(left) == normalize(right)
1900	}
