1929	/// The manifest keys the crate turns into run-time refusals have to be there
1930	/// and parse. A directory generated before one of them exists would otherwise
1931	/// build, report its bodies as real, and refuse nothing.
1932	fn checked_manifest_fields(family: &TileLangFamily, artifacts: &TileLangArtifacts) {
1933	    for key in family.required_manifest {
1934	        let value = match *key {
1935	            "ARCH" => artifacts.arch.as_deref(),
1936	            "GEOMETRY" => artifacts.geometry.as_deref(),
1937	            "SMEM" => artifacts.smem.as_deref(),
1938	            other => panic!("{} names an unknown manifest key {other}", family.label),
1939	        };
1940	        let ok = match (*key, value) {
1941	            (_, None | Some("")) => false,
1942	            ("SMEM", Some(text)) => text.parse::<usize>().is_ok(),
1943	            ("GEOMETRY", Some(text)) => {
1944	                text.split(',').count() == 4
1945	                    && text.split(',').all(|f| f.trim().parse::<usize>().is_ok())
1946	            }
1947	            _ => true,
1948	        };
1949	        assert!(
1950	            ok,
1951	            "the {} TileLang artifacts state {key}={}, which the crate needs to refuse a \
1952	             device or checkpoint the bodies cannot serve; regenerate the directory with \
1953	             the current generator",
1954	            family.label,
1955	            value.unwrap_or("<missing>")
1956	        );
1957	    }
1958	}
