        let (gdr_recompute_func, gdr_recompute_c) =
            generate_triton_artifacts(&python, out_dir, &triton_target, &gdr_recompute_spec);
        let gdr_recompute_wrapper = write_wrapper(
            &gdr_recompute_c,
